ANGLES = [
    "実はどうなっているのか",
    "なぜそうなるのか",
    "意外な理由",
    "知らないと気づきにくい仕組み",
    "身近なのに不思議なポイント",
    "昔と今で何が変わったのか",
    "意外と知られていない事実",
    "一見すると普通なのに不思議な部分",
    "人が勘違いしやすいポイント",
    "知ると見方が変わるポイント",
]

HOOKS = [
    "実は、ここには意外な理由があります。",
    "でも、面白いのはここからです。",
    "ところが、よく考えると不思議なことがあります。",
    "ここで一つ意外なポイントがあります。",
    "普通に見えますが、実はそう単純ではありません。",
    "そして、ここからが面白いところです。",
    "多くの人が見落としがちなのが、この部分です。",
    "実際に仕組みを知ると、少し見え方が変わります。",
    "ここには意外な共通点があります。",
    "さらに面白いことがあります。",
]

def make_fact(category, topic, angle, number):
    hook = HOOKS[number % len(HOOKS)]

    return {
        "id": number,
        "category": category,
        "topic": topic,
        "angle": angle,
        "hook": hook,
        "fact": f"{topic}についての「{angle}」をテーマにした雑学ネタ。"
    }


# 2000件作成
items = []
number = 1

for category, topics in BASE_TOPICS.items():
    for topic in topics:
        for angle in ANGLES:
            items.append(
                make_fact(
                    category,
                    topic,
                    angle,
                    number
                )
            )
            number += 1

# 念のためシャッフル
random.shuffle(items)

# IDを振り直す
for i, item in enumerate(items, 1):
    item["id"] = i

# 2000件に限定
items = items[:2000]

with open("trivia.json", "w", encoding="utf-8") as f:
    json.dump(
        items,
        f,
        ensure_ascii=False,
        indent=2
    )

print("================================")
